import json, subprocess, time, os, sys

def run(cmd):
    r = subprocess.run(cmd, capture_output=True, text=True, shell=True)
    return r.stdout.strip(), r.stderr.strip(), r.returncode

# ── STEP 1: CLOSE ALL BROKEN PRs FROM saurabhhhcodes ─────────────────────────
print("=== STEP 1: Closing broken PRs ===")
stdout, _, _ = run('gh pr list --limit 300 --state open --json number,author --jq "[.[] | select(.author.login==\\"saurabhhhcodes\\") | .number]"')
pr_nums = json.loads(stdout) if stdout else []
print(f"Found {len(pr_nums)} broken PRs to close")

close_msg = """Hi @saurabhhhcodes, thank you for your interest in contributing to this project! 🙏

Unfortunately, after carefully reviewing this PR, we found that the changes contain **syntax errors and malformed code** that would break the application if merged. For example:
- Invalid arrow function syntax (missing parameter in `.catch()`)  
- Code placed outside of React component scope  
- Incomplete or misplaced statements

These appear to be auto-generated fixes that are not compatible with our codebase structure.

We are closing this PR to keep the repository clean and stable. If you'd like to contribute:
1. **Fork** the repository and clone it locally
2. **Identify** a specific bug or issue to fix
3. **Test** your changes locally before submitting
4. **Open a PR** with a clear description of what was fixed and why

We truly appreciate your enthusiasm and look forward to a well-crafted contribution in the future! 🚀"""

with open("close_msg.txt", "w", encoding="utf-8") as f:
    f.write(close_msg)

for num in pr_nums:
    print(f"  Closing PR #{num}")
    run(f'gh pr comment {num} --body-file close_msg.txt')
    run(f'gh pr close {num}')
    time.sleep(0.8)

print(f"Closed {len(pr_nums)} broken PRs\n")


